-- Evaluation-only tables (source invoices, ground truth). Load after seed.sql.
-- Generated by `python -m invoice_ap export` from the spec and the layer CSVs.
PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;

CREATE TABLE invoice (
  invoice_id TEXT NOT NULL,
  doc_id TEXT NOT NULL,
  vendor_id TEXT NOT NULL,
  vendor_invoice_number TEXT NOT NULL,
  invoice_date TEXT NOT NULL CHECK ((invoice_date = date(invoice_date)) OR invoice_date IS NULL),
  po_id TEXT,
  attention_user_id TEXT,
  currency TEXT NOT NULL CHECK ((currency IN ('INR')) OR currency IS NULL),
  header_net_amount NUMERIC NOT NULL CHECK ((header_net_amount >= 0.00) OR header_net_amount IS NULL),
  header_tax_amount NUMERIC NOT NULL CHECK ((header_tax_amount >= 0.00) OR header_tax_amount IS NULL),
  header_gross_amount NUMERIC NOT NULL CHECK ((header_gross_amount >= 0.00) OR header_gross_amount IS NULL),
  lines_net_amount NUMERIC NOT NULL CHECK ((lines_net_amount >= 0.00) OR lines_net_amount IS NULL),
  lines_tax_amount NUMERIC NOT NULL CHECK ((lines_tax_amount >= 0.00) OR lines_tax_amount IS NULL),
  lines_gross_amount NUMERIC NOT NULL CHECK ((lines_gross_amount >= 0.00) OR lines_gross_amount IS NULL),
  line_count INTEGER NOT NULL CHECK ((line_count >= 1) OR line_count IS NULL),
  is_po_backed INTEGER NOT NULL CHECK ((is_po_backed IN (0, 1)) OR is_po_backed IS NULL),
  PRIMARY KEY (invoice_id),
  UNIQUE (doc_id),
  FOREIGN KEY (doc_id) REFERENCES intake_manifest (doc_id),
  FOREIGN KEY (vendor_id) REFERENCES vendor (vendor_id),
  FOREIGN KEY (po_id) REFERENCES purchase_order (po_id),
  FOREIGN KEY (attention_user_id) REFERENCES app_user (user_id)
);

CREATE TABLE invoice_line (
  invoice_line_id TEXT NOT NULL,
  invoice_id TEXT NOT NULL,
  line_number INTEGER NOT NULL CHECK ((line_number >= 1) OR line_number IS NULL),
  po_line_id TEXT,
  sku_id TEXT,
  description TEXT NOT NULL,
  uom TEXT NOT NULL CHECK ((uom IN ('EA', 'BOX', 'PACK', 'SET', 'KG', 'L', 'M', 'HR', 'MONTH', 'JOB')) OR uom IS NULL),
  quantity NUMERIC NOT NULL CHECK ((quantity >= 0.01) OR quantity IS NULL),
  unit_price NUMERIC NOT NULL CHECK ((unit_price >= 0.01) OR unit_price IS NULL),
  line_net_amount NUMERIC NOT NULL CHECK ((line_net_amount >= 0.00) OR line_net_amount IS NULL),
  tax_code TEXT NOT NULL CHECK ((tax_code IN ('GST0', 'GST5', 'GST12', 'GST18', 'EXEMPT')) OR tax_code IS NULL),
  tax_rate_pct NUMERIC NOT NULL,
  tax_amount NUMERIC NOT NULL CHECK ((tax_amount >= 0.00) OR tax_amount IS NULL),
  expected_line_net_amount NUMERIC NOT NULL CHECK ((expected_line_net_amount >= 0.00) OR expected_line_net_amount IS NULL),
  expected_tax_amount NUMERIC NOT NULL CHECK ((expected_tax_amount >= 0.00) OR expected_tax_amount IS NULL),
  line_gross_amount NUMERIC NOT NULL CHECK ((line_gross_amount >= 0.00) OR line_gross_amount IS NULL),
  PRIMARY KEY (invoice_line_id),
  UNIQUE (invoice_id, line_number),
  FOREIGN KEY (invoice_id) REFERENCES invoice (invoice_id),
  FOREIGN KEY (po_line_id) REFERENCES purchase_order_line (po_line_id),
  FOREIGN KEY (sku_id) REFERENCES sku (sku_id),
  FOREIGN KEY (tax_code) REFERENCES tax_code (tax_code)
);

CREATE TABLE ground_truth (
  invoice_id TEXT NOT NULL,
  doc_id TEXT NOT NULL,
  scenario_category TEXT NOT NULL CHECK ((scenario_category IN ('CLEAN', 'PRICE_VARIANCE', 'QTY_MISMATCH', 'DUPLICATE', 'MISSING_RECEIPT', 'TAX_VENDOR', 'ARITHMETIC', 'INVOICE_BEFORE_PO', 'CAPTURE_REVIEW')) OR scenario_category IS NULL),
  scenario_code TEXT NOT NULL CHECK ((scenario_code IN ('C-STD', 'C-PARTIAL-OPEN', 'C-OVERRECEIPT-WITHIN', 'C-QTY-AT-TOL', 'C-PRICE-AT-TOL', 'C-PRICE-INSIDE', 'C-PRICE-SMALL-VAR', 'C-TAX-ROUNDING', 'C-TN-SAME-DAY', 'C-SPLIT-PARTIAL', 'C-SPLIT-FINAL', 'C-CONSOLIDATED', 'C-PARTIAL-BILLING', 'C-NPO-RECURRING', 'C-NPO-ONEOFF', 'PV-OVER', 'PV-SPLIT-LATER', 'PV-UNDER', 'PV-BOUNDARY-OUT', 'QM-PARTIAL-BILLED-FULL', 'QM-OVERBILL-RECEIVED', 'QM-CUMULATIVE', 'QM-EXCEEDS-PO-OVERRECEIPT', 'QM-EXCEEDS-PO-AND-RECEIVED', 'QM-BOUNDARY-OUT', 'DUP-EXACT', 'DUP-EXACT-NORMALIZED', 'DUP-EXACT-NPO', 'DUP-NUMBER-REUSE', 'DUP-CONTENT', 'MR-NO-GRN', 'TV-CLOSED', 'TV-BLOCKED', 'TV-TAX-CODE', 'TV-TAX-AMOUNT', 'TV-VENDOR-PO', 'TV-NPO-TAX-AMOUNT', 'ARITH-HEADER-TOTAL', 'ARITH-LINE-EXTENSION', 'DATE-INVOICE-BEFORE-PO', 'CAP-DEGRADED-SCAN')) OR scenario_code IS NULL),
  edge_case_ids TEXT,
  is_anomaly INTEGER NOT NULL CHECK ((is_anomaly IN (0, 1)) OR is_anomaly IS NULL),
  is_po_backed INTEGER NOT NULL CHECK ((is_po_backed IN (0, 1)) OR is_po_backed IS NULL),
  capture_overlay TEXT NOT NULL CHECK ((capture_overlay IN ('NONE', 'DEGRADED_SCAN')) OR capture_overlay IS NULL),
  intended_issue_types TEXT,
  expected_issue_types TEXT,
  expected_primary_issue TEXT NOT NULL CHECK ((expected_primary_issue IN ('EXT_LOW_CONFIDENCE', 'DUPLICATE_EXACT', 'DUPLICATE_NUMBER_REUSE', 'DUPLICATE_SUSPECTED', 'VENDOR_NOT_FOUND', 'VENDOR_SENDER_MISMATCH', 'VENDOR_CLOSED', 'VENDOR_BLOCKED', 'PO_NOT_FOUND', 'VENDOR_PO_MISMATCH', 'INVOICE_DATE_IN_FUTURE', 'INVOICE_BEFORE_PO', 'HEADER_TOTAL_MISMATCH', 'LINE_AMOUNT_MISMATCH', 'TAX_CODE_INVALID', 'TAX_CODE_MISMATCH', 'TAX_AMOUNT_MISMATCH', 'PO_LINE_UNMATCHED', 'MISSING_RECEIPT', 'QTY_EXCEEDS_PO', 'QTY_EXCEEDS_RECEIVED', 'PRICE_VARIANCE', 'VENDOR_NOT_PAYABLE', 'PAYMENT_DUE_DATE_PASSED', 'NONE')) OR expected_primary_issue IS NULL),
  expected_blocked INTEGER NOT NULL CHECK ((expected_blocked IN (0, 1)) OR expected_blocked IS NULL),
  expected_match_status TEXT NOT NULL CHECK ((expected_match_status IN ('MATCHED', 'MATCHED_WITHIN_TOLERANCE', 'PRICE_VARIANCE', 'QTY_MISMATCH', 'MISSING_RECEIPT', 'TAX_MISMATCH', 'NOT_APPLICABLE', 'NOT_EVALUATED')) OR expected_match_status IS NULL),
  expected_duplicate_of TEXT,
  expected_assigned_roles TEXT,
  expected_queues TEXT,
  expected_approval_band TEXT,
  expected_approval_levels TEXT,
  expected_final_status TEXT NOT NULL CHECK ((expected_final_status IN ('RECEIVED', 'CAPTURED', 'ON_HOLD', 'REJECTED', 'PENDING_APPROVAL', 'APPROVED', 'PAYMENT_READY', 'PAID')) OR expected_final_status IS NULL),
  expected_payment_ready INTEGER NOT NULL CHECK ((expected_payment_ready IN (0, 1)) OR expected_payment_ready IS NULL),
  expected_payment_status TEXT CHECK ((expected_payment_status IN ('SCHEDULED', 'PAID')) OR expected_payment_status IS NULL),
  expected_due_date TEXT CHECK ((expected_due_date = date(expected_due_date)) OR expected_due_date IS NULL),
  expected_scheduled_date TEXT CHECK ((expected_scheduled_date = date(expected_scheduled_date)) OR expected_scheduled_date IS NULL),
  oracle_rule_ids TEXT,
  policy_version TEXT NOT NULL,
  description TEXT NOT NULL,
  PRIMARY KEY (invoice_id),
  UNIQUE (doc_id),
  FOREIGN KEY (invoice_id) REFERENCES invoice (invoice_id),
  FOREIGN KEY (doc_id) REFERENCES intake_manifest (doc_id),
  FOREIGN KEY (expected_duplicate_of) REFERENCES invoice (invoice_id)
);

CREATE TABLE ground_truth_line (
  invoice_line_id TEXT NOT NULL,
  invoice_id TEXT NOT NULL,
  expected_line_issue_types TEXT,
  expected_price_status TEXT NOT NULL CHECK ((expected_price_status IN ('EXACT', 'WITHIN_TOLERANCE', 'OUT_OF_TOLERANCE', 'NOT_EVALUATED')) OR expected_price_status IS NULL),
  expected_qty_status TEXT NOT NULL CHECK ((expected_qty_status IN ('OK', 'EXCEEDS_RECEIVED', 'EXCEEDS_PO', 'NO_RECEIPT', 'NOT_EVALUATED')) OR expected_qty_status IS NULL),
  expected_tax_status TEXT NOT NULL CHECK ((expected_tax_status IN ('OK', 'WITHIN_ROUNDING', 'CODE_MISMATCH', 'AMOUNT_MISMATCH', 'NOT_EVALUATED')) OR expected_tax_status IS NULL),
  expected_received_qty NUMERIC CHECK ((expected_received_qty >= 0) OR expected_received_qty IS NULL),
  expected_prior_invoiced_qty NUMERIC CHECK ((expected_prior_invoiced_qty >= 0) OR expected_prior_invoiced_qty IS NULL),
  expected_price_variance_pct NUMERIC,
  PRIMARY KEY (invoice_line_id),
  FOREIGN KEY (invoice_line_id) REFERENCES invoice_line (invoice_line_id),
  FOREIGN KEY (invoice_id) REFERENCES invoice (invoice_id)
);

COMMIT;
